/// Parse POSIX-style argv into Options.  args[0] is the program name
/// (skipped); `--` ends flag parsing; every matched flag sets its
/// field, coerced inline (the Dhall type never sees argv strings).
/// Accepted spellings: exact short/long tokens, argumentless short
/// clusters (-la == -l -a; a Value short never clusters) and inline
/// --long=value for Value longs.  Text operands are gpa-owned
/// dupes on success; on error earlier dupes are not freed (same
/// discipline as the hand parsers this replaces).
pub fn parsePosix(args: []const []const u8, gpa: Allocator) ParseError!Options {
    var seen: u32 = 0; // bit i set once flags[i] matched
    var next_pos: usize = 0; // next single-positional slot to fill
    var o = Options{};
    var i: usize = 1;
    var after_ddash = false;
    while (i < args.len) : (i += 1) {
        const a = args[i];
        if (after_ddash) {
            try bindOperand(a, &o, &next_pos, gpa);
            continue;
        }
        if (std.mem.eql(u8, a, "--")) {
            after_ddash = true;
            continue;
        }
        var matched = false;
        if (a.len > 2 and a[0] == '-' and a[1] != '-') {
            var cluster = true;
            for (a[1..]) |ch| {
                var letter_matched = false;
                if (ch == 'u') {
                    if ((seen & (1 << 1)) != 0) {
                        std.debug.print("fx-id: options '-u' and '-g' are mutually exclusive\n", .{});
                        return error.Conflict;
                    }
                    if ((seen & (1 << 2)) != 0) {
                        std.debug.print("fx-id: options '-u' and '-G' are mutually exclusive\n", .{});
                        return error.Conflict;
                    }
                    o.uid = true;
                    seen |= 1 << 0;
                    letter_matched = true;
                }
                if (ch == 'g') {
                    if ((seen & (1 << 0)) != 0) {
                        std.debug.print("fx-id: options '-g' and '-u' are mutually exclusive\n", .{});
                        return error.Conflict;
                    }
                    if ((seen & (1 << 2)) != 0) {
                        std.debug.print("fx-id: options '-g' and '-G' are mutually exclusive\n", .{});
                        return error.Conflict;
                    }
                    o.gid = true;
                    seen |= 1 << 1;
                    letter_matched = true;
                }
                if (ch == 'G') {
                    if ((seen & (1 << 0)) != 0) {
                        std.debug.print("fx-id: options '-G' and '-u' are mutually exclusive\n", .{});
                        return error.Conflict;
                    }
                    if ((seen & (1 << 1)) != 0) {
                        std.debug.print("fx-id: options '-G' and '-g' are mutually exclusive\n", .{});
                        return error.Conflict;
                    }
                    o.all = true;
                    seen |= 1 << 2;
                    letter_matched = true;
                }
                if (ch == 'n') {
                    o.names = true;
                    seen |= 1 << 3;
                    letter_matched = true;
                }
                if (ch == 'r') {
                    o.real = true;
                    seen |= 1 << 4;
                    letter_matched = true;
                }
                if (!letter_matched) cluster = false;
            }
            if (cluster) continue;
        }
        if (!matched and (std.mem.eql(u8, a, "-u"))) {
            if ((seen & (1 << 1)) != 0) {
                std.debug.print("fx-id: options '-u' and '-g' are mutually exclusive\n", .{});
                return error.Conflict;
            }
            if ((seen & (1 << 2)) != 0) {
                std.debug.print("fx-id: options '-u' and '-G' are mutually exclusive\n", .{});
                return error.Conflict;
            }
            o.uid = true;
            seen |= 1 << 0;
            matched = true;
        }
        if (!matched and (std.mem.eql(u8, a, "-g"))) {
            if ((seen & (1 << 0)) != 0) {
                std.debug.print("fx-id: options '-g' and '-u' are mutually exclusive\n", .{});
                return error.Conflict;
            }
            if ((seen & (1 << 2)) != 0) {
                std.debug.print("fx-id: options '-g' and '-G' are mutually exclusive\n", .{});
                return error.Conflict;
            }
            o.gid = true;
            seen |= 1 << 1;
            matched = true;
        }
        if (!matched and (std.mem.eql(u8, a, "-G"))) {
            if ((seen & (1 << 0)) != 0) {
                std.debug.print("fx-id: options '-G' and '-u' are mutually exclusive\n", .{});
                return error.Conflict;
            }
            if ((seen & (1 << 1)) != 0) {
                std.debug.print("fx-id: options '-G' and '-g' are mutually exclusive\n", .{});
                return error.Conflict;
            }
            o.all = true;
            seen |= 1 << 2;
            matched = true;
        }
        if (!matched and (std.mem.eql(u8, a, "-n"))) {
            o.names = true;
            seen |= 1 << 3;
            matched = true;
        }
        if (!matched and (std.mem.eql(u8, a, "-r"))) {
            o.real = true;
            seen |= 1 << 4;
            matched = true;
        }
        if (!matched) {
            if (a.len > 1 and a[0] == '-') {
                std.debug.print("fx-id: unknown option '{s}'\n", .{ a });
                return error.UnknownOption;
            }
            try bindOperand(a, &o, &next_pos, gpa);
        }
    }
    return o;
}

fn bindOperand(arg: []const u8, o: *Options, next_pos: *usize, gpa: Allocator) ParseError!void {
    if (next_pos.* == 0) {
        o.user = gpa.dupe(u8, arg) catch return error.OutOfMemory;
        next_pos.* = 1;
        return;
    }
    std.debug.print("fx-id: unexpected operand '{s}'\n", .{ arg });
    return error.UnexpectedOperand;
}

pub fn usage() []const u8 {
    return "usage: fx-id [OPTIONS] [USER]\n";
}

test "cli_id: empty argv yields the dflt defaults" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const gpa = arena_state.allocator();
    const argv = [_][]const u8{ "fx-id" };
    const o = try parsePosix(&argv, gpa);
    try std.testing.expectEqual(false, o.all);
    try std.testing.expectEqual(false, o.gid);
    try std.testing.expectEqual(false, o.names);
    try std.testing.expectEqual(false, o.real);
    try std.testing.expectEqual(false, o.uid);
    try std.testing.expectEqualStrings("", o.user);
}

